// This file sets up Vitest globals for TypeScript
import { expect, vi } from "vitest";

// Re-export Vitest globals
global.expect = expect;
global.vi = vi;

/**
 * Test setup utilities for MCP Gemini Server tests
 *
 * This file provides helper functions for setting up and tearing down the server during tests,
 * as well as creating test fixtures and mock objects.
 */

import { Server } from "node:http";
import { AddressInfo } from "node:net";
import { setTimeout } from "node:timers/promises";

/**
 * Options for creating a test server
 */
export interface TestServerOptions {
  /** Port to run the server on (0 for random port) */
  port?: number;
  /** API key to use (defaults to environment variable) */
  apiKey?: string;
  /** Default model to use for tests */
  defaultModel?: string;
  /** Base directory for file operations during tests */
  fileBasePath?: string;
  /** Whether to use verbose logging during tests */
  verbose?: boolean;
}

/**
 * Context object returned by setupTestServer
 */
export interface TestServerContext {
  /** The HTTP server instance */
  server: Server;
  /** The base URL to connect to the server */
  baseUrl: string;
  /** Port the server is running on */
  port: number;
  /** Function to cleanly shut down the server */
  teardown: () => Promise<void>;
  /** GeminiService instance for mocking */
  geminiService: object;
}

/**
 * Sets up a test server with the specified options
 *
 * @param options - Configuration options for the test server
 * @returns TestServerContext object with server and helper methods
 */
export async function setupTestServer(
  options: TestServerOptions = {}
): Promise<TestServerContext> {
  // Save original environment variables
  const originalEnv = {
    GOOGLE_GEMINI_API_KEY: process.env.GOOGLE_GEMINI_API_KEY,
    GOOGLE_GEMINI_MODEL: process.env.GOOGLE_GEMINI_MODEL,
    GEMINI_SAFE_FILE_BASE_DIR: process.env.GEMINI_SAFE_FILE_BASE_DIR,
    NODE_ENV: process.env.NODE_ENV,
  };

  // Set test environment variables
  process.env.NODE_ENV = "test";
  if (options.apiKey) {
    process.env.GOOGLE_GEMINI_API_KEY = options.apiKey;
  }
  if (options.defaultModel) {
    process.env.GOOGLE_GEMINI_MODEL = options.defaultModel;
  }
  if (options.fileBasePath) {
    process.env.GEMINI_SAFE_FILE_BASE_DIR = options.fileBasePath;
  }

  // Import server creation functions
  const { createServer } = await import("../../src/createServer.js");
  const http = await import("node:http");

  // Create MCP server instance
  // This is intentionally unused in the test setup but kept for reference
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const { server: mcpServer, mcpClientService } = createServer();

  // Type assertion pattern: McpClientService -> { geminiService: object }
  // This double assertion is necessary because:
  // 1. McpClientService doesn't formally expose geminiService in its type definition
  // 2. We need to access it for test mocking purposes
  // 3. The service implementation actually contains this property at runtime
  const geminiService = (
    mcpClientService as unknown as { geminiService: object }
  ).geminiService;

  // Create an HTTP server using the MCP server
  const port = options.port || 0;
  const httpServer = http.createServer();

  // Create a request handler
  httpServer.on("request", (req, res) => {
    // Since McpServer doesn't directly handle HTTP requests like Express middleware,
    // we need to create a compatible transport or adapter here.
    // For testing purposes, we'll implement a basic response
    res.setHeader("Content-Type", "application/json");
    res.writeHead(200);
    res.end(
      JSON.stringify({
        status: "ok",
        message:
          "This is a mock response for testing. In a real implementation, requests would be processed through the McpServer transport layer.",
      })
    );
  });

  // Start the HTTP server
  httpServer.listen(port);

  // Wait for the server to be ready
  await new Promise<void>((resolve) => {
    httpServer.once("listening", () => resolve());
  });

  // Get the actual port (in case it was randomly assigned)
  const actualPort = (httpServer.address() as AddressInfo).port;
  const baseUrl = `http://localhost:${actualPort}`;

  // Return the context with server and helper methods
  return {
    server: httpServer,
    baseUrl,
    port: actualPort,
    geminiService,
    teardown: async () => {
      // Close the HTTP server
      await new Promise<void>((resolve, reject) => {
        httpServer.close((err: Error | undefined) => {
          if (err) reject(err);
          else resolve();
        });
      });

      // Restore original environment variables
      process.env.GOOGLE_GEMINI_API_KEY = originalEnv.GOOGLE_GEMINI_API_KEY;
      process.env.GOOGLE_GEMINI_MODEL = originalEnv.GOOGLE_GEMINI_MODEL;
      process.env.GEMINI_SAFE_FILE_BASE_DIR =
        originalEnv.GEMINI_SAFE_FILE_BASE_DIR;
      process.env.NODE_ENV = originalEnv.NODE_ENV;

      // Small delay to ensure cleanup completes
      await setTimeout(100);
    },
  };
}

/**
 * Interface for mock API responses
 */
export interface MockApiResponse<T> {
  status: number;
  data: T;
  headers: Record<string, string>;
  config: Record<string, unknown>;
  request: Record<string, unknown>;
}

/**
 * Creates a mock API response object for testing
 *
 * @param status - HTTP status code to return
 * @param data - Response data
 * @returns Mock response object
 */
export function createMockResponse<T>(
  status: number,
  data: T
): MockApiResponse<T> {
  return {
    status,
    data,
    headers: {},
    config: {},
    request: {},
  };
}

/**
 * Check if required environment variables for testing are available
 *
 * @param requiredVars - Array of required environment variable names
 * @returns true if all variables are available, false otherwise
 */
export function checkRequiredEnvVars(
  requiredVars: string[] = ["GOOGLE_GEMINI_API_KEY"]
): boolean {
  const missing = requiredVars.filter((varName) => !process.env[varName]);
  if (missing.length > 0) {
    console.warn(
      `Missing required environment variables for testing: ${missing.join(", ")}`
    );
    console.warn(
      "Create a .env.test file or set these variables in your environment"
    );
    return false;
  }
  return true;
}

/**
 * Interface for test context that can be skipped
 */
export interface SkippableTestContext {
  skip: (reason: string) => void;
}

/**
 * Skip a test if required environment variables are missing
 *
 * @param t - Test context
 * @param requiredVars - Array of required environment variable names
 * @returns Whether the test should be skipped
 */
export function skipIfMissingEnvVars(
  t: SkippableTestContext,
  requiredVars: string[] = ["GOOGLE_GEMINI_API_KEY"]
): boolean {
  const missing = requiredVars.filter((varName) => !process.env[varName]);
  if (missing.length > 0) {
    t.skip(`Test requires environment variables: ${missing.join(", ")}`);
    return true;
  }
  return false;
}

import { describe, it, beforeEach, afterEach, expect, vi } from "vitest";
import * as path from "path";
import * as fs from "fs/promises";
import * as fsSync from "fs";

// Import the code to test
import { FileSecurityService } from "../../../src/utils/FileSecurityService.js";
import { ValidationError } from "../../../src/utils/errors.js";
import { logger } from "../../../src/utils/logger.js";

describe("FileSecurityService", () => {
  // Mock logger
  const loggerMock = {
    info: vi.fn(),
    warn: vi.fn(),
    error: vi.fn(),
    debug: vi.fn(),
  };

  // Define test constants for all tests
  const TEST_CONTENT = "Test file content";
  const TEST_DIR = path.resolve("./test-security-dir");
  const OUTSIDE_DIR = path.resolve("./outside-security-dir");

  // Setup before each test
  beforeEach(() => {
    // Reset mocks and create test directories
    vi.clearAllMocks();

    // Replace logger with mock
    vi.spyOn(logger, "info").mockImplementation(loggerMock.info);
    vi.spyOn(logger, "warn").mockImplementation(loggerMock.warn);
    vi.spyOn(logger, "error").mockImplementation(loggerMock.error);
    vi.spyOn(logger, "debug").mockImplementation(loggerMock.debug);

    // Create test directories
    fsSync.mkdirSync(TEST_DIR, { recursive: true });
    fsSync.mkdirSync(OUTSIDE_DIR, { recursive: true });
  });

  // Cleanup after each test
  afterEach(() => {
    // Restore original logger
    vi.restoreAllMocks();

    // Clean up test directories
    try {
      fsSync.rmSync(TEST_DIR, { recursive: true, force: true });
      fsSync.rmSync(OUTSIDE_DIR, { recursive: true, force: true });
    } catch (err) {
      // Ignore cleanup errors
    }
  });

  describe("Constructor and Configuration", () => {
    it("should initialize with default allowed directories", () => {
      const service = new FileSecurityService();
      const allowedDirs = service.getAllowedDirectories();

      expect(allowedDirs.length).toBeGreaterThan(0);
      expect(allowedDirs).toContain(path.resolve(process.cwd()));
    });

    it("should initialize with custom allowed directories", () => {
      const customDirs = [TEST_DIR, OUTSIDE_DIR];
      const service = new FileSecurityService(customDirs);
      const allowedDirs = service.getAllowedDirectories();

      expect(allowedDirs.length).toBe(2);
      expect(allowedDirs).toContain(path.resolve(TEST_DIR));
      expect(allowedDirs).toContain(path.resolve(OUTSIDE_DIR));
    });

    it("should initialize with a secure base path", () => {
      const service = new FileSecurityService([], TEST_DIR);
      const basePath = service.getSecureBasePath();

      expect(basePath).toBe(path.normalize(TEST_DIR));

      // Verify allowed directories includes the base path
      const allowedDirs = service.getAllowedDirectories();
      expect(allowedDirs).toContain(path.normalize(TEST_DIR));
    });

    it("should set allowed directories", () => {
      const service = new FileSecurityService();
      const newDirs = [TEST_DIR, OUTSIDE_DIR];

      service.setAllowedDirectories(newDirs);
      const allowedDirs = service.getAllowedDirectories();

      expect(allowedDirs.length).toBe(2);
      expect(allowedDirs).toContain(path.normalize(TEST_DIR));
      expect(allowedDirs).toContain(path.normalize(OUTSIDE_DIR));
    });

    it("should throw error when setting empty allowed directories", () => {
      const service = new FileSecurityService();

      expect(() => service.setAllowedDirectories([])).toThrow(ValidationError);
      expect(() => service.setAllowedDirectories([])).toThrow(
        /At least one allowed directory/
      );
    });

    it("should throw error when setting non-absolute allowed directories", () => {
      const service = new FileSecurityService();

      expect(() => service.setAllowedDirectories(["./relative/path"])).toThrow(
        ValidationError
      );
      expect(() => service.setAllowedDirectories(["./relative/path"])).toThrow(
        /Directory path must be absolute/
      );
    });

    it("should set and get secure base path", () => {
      const service = new FileSecurityService();
      service.setSecureBasePath(TEST_DIR);

      const basePath = service.getSecureBasePath();
      expect(basePath).toBe(path.normalize(TEST_DIR));
    });

    it("should throw error when setting non-absolute secure base path", () => {
      const service = new FileSecurityService();

      expect(() => service.setSecureBasePath("./relative/path")).toThrow(
        ValidationError
      );
      expect(() => service.setSecureBasePath("./relative/path")).toThrow(
        /Base path must be absolute/
      );
    });

    it("should configure from environment", () => {
      // Save original env var
      const originalEnvVar = process.env.GEMINI_SAFE_FILE_BASE_DIR;

      // Set env var for test
      process.env.GEMINI_SAFE_FILE_BASE_DIR = TEST_DIR;

      const service = FileSecurityService.configureFromEnvironment();
      const allowedDirs = service.getAllowedDirectories();

      expect(allowedDirs).toContain(path.normalize(TEST_DIR));

      // Restore original env var
      if (originalEnvVar) {
        process.env.GEMINI_SAFE_FILE_BASE_DIR = originalEnvVar;
      } else {
        delete process.env.GEMINI_SAFE_FILE_BASE_DIR;
      }
    });
  });

  describe("Path Validation", () => {
    let service: FileSecurityService;

    beforeEach(() => {
      service = new FileSecurityService([TEST_DIR]);
    });

    it("should validate path within allowed directory", () => {
      const testFilePath = path.join(TEST_DIR, "test-file.txt");
      const validatedPath = service.validateAndResolvePath(testFilePath);

      expect(validatedPath).toBe(path.normalize(testFilePath));
    });

    it("should validate paths with relative components", () => {
      const complexPath = path.join(
        TEST_DIR,
        ".",
        "subdir",
        "..",
        "test-file.txt"
      );
      const validatedPath = service.validateAndResolvePath(complexPath);

      // Should normalize to TEST_DIR/test-file.txt
      const expectedPath = path.normalize(path.join(TEST_DIR, "test-file.txt"));
      expect(validatedPath).toBe(expectedPath);
    });

    it("should reject paths outside allowed directories", () => {
      const outsidePath = path.join(OUTSIDE_DIR, "test-file.txt");

      expect(() => service.validateAndResolvePath(outsidePath)).toThrow(
        ValidationError
      );
      expect(() => service.validateAndResolvePath(outsidePath)).toThrow(
        /Access denied/
      );
    });

    it("should reject paths with directory traversal", () => {
      const traversalPath = path.join(
        TEST_DIR,
        "..",
        "outside",
        "test-file.txt"
      );

      expect(() => service.validateAndResolvePath(traversalPath)).toThrow(
        ValidationError
      );
      expect(() => service.validateAndResolvePath(traversalPath)).toThrow(
        /Access denied/
      );
    });

    it("should check file existence with mustExist option", () => {
      const nonExistentPath = path.join(TEST_DIR, "non-existent.txt");

      expect(() =>
        service.validateAndResolvePath(nonExistentPath, { mustExist: true })
      ).toThrow(ValidationError);
      expect(() =>
        service.validateAndResolvePath(nonExistentPath, { mustExist: true })
      ).toThrow(/File not found/);
    });

    it("should use custom allowed directories when provided", () => {
      // Path is outside the service's configured directory but inside custom allowed dir
      const customAllowedPath = path.join(OUTSIDE_DIR, "custom-allowed.txt");

      const validatedPath = service.validateAndResolvePath(customAllowedPath, {
        allowedDirs: [OUTSIDE_DIR],
      });

      expect(validatedPath).toBe(path.normalize(customAllowedPath));
    });
  });

  describe("isPathWithinAllowedDirs", () => {
    let service: FileSecurityService;

    beforeEach(() => {
      service = new FileSecurityService([TEST_DIR]);
    });

    it("should return true for paths within allowed directories", () => {
      const insidePath = path.join(TEST_DIR, "test-file.txt");
      const result = service.isPathWithinAllowedDirs(insidePath);

      expect(result).toBe(true);
    });

    it("should return true for exact match with allowed directory", () => {
      const result = service.isPathWithinAllowedDirs(TEST_DIR);

      expect(result).toBe(true);
    });

    it("should return false for paths outside allowed directories", () => {
      const outsidePath = path.join(OUTSIDE_DIR, "test-file.txt");
      const result = service.isPathWithinAllowedDirs(outsidePath);

      expect(result).toBe(false);
    });

    it("should return false for paths with directory traversal", () => {
      const traversalPath = path.join(
        TEST_DIR,
        "..",
        "outside",
        "test-file.txt"
      );
      const result = service.isPathWithinAllowedDirs(traversalPath);

      expect(result).toBe(false);
    });

    it("should use custom allowed directories when provided", () => {
      const outsidePath = path.join(OUTSIDE_DIR, "test-file.txt");

      // Should be false with default allowed dirs
      expect(service.isPathWithinAllowedDirs(outsidePath)).toBe(false);

      // Should be true with custom allowed dirs
      expect(service.isPathWithinAllowedDirs(outsidePath, [OUTSIDE_DIR])).toBe(
        true
      );
    });

    it("should return false when no allowed directories exist", () => {
      const result = service.isPathWithinAllowedDirs(TEST_DIR, []);

      expect(result).toBe(false);
    });
  });

  describe("fullyResolvePath", () => {
    let service: FileSecurityService;

    beforeEach(() => {
      service = new FileSecurityService([TEST_DIR, OUTSIDE_DIR]);
    });

    it("should resolve a normal file path", async () => {
      const testPath = path.join(TEST_DIR, "test-file.txt");
      const resolvedPath = await service.fullyResolvePath(testPath);

      expect(resolvedPath).toBe(path.normalize(testPath));
    });

    it("should handle non-existent paths", async () => {
      const nonExistentPath = path.join(
        TEST_DIR,
        "non-existent",
        "test-file.txt"
      );
      const resolvedPath = await service.fullyResolvePath(nonExistentPath);

      expect(resolvedPath).toBe(path.normalize(nonExistentPath));
    });

    it("should resolve and validate a symlink to a file", async () => {
      // Create target file
      const targetPath = path.join(TEST_DIR, "target.txt");
      await fs.writeFile(targetPath, TEST_CONTENT, "utf8");

      // Create symlink
      const symlinkPath = path.join(TEST_DIR, "symlink.txt");
      await fs.symlink(targetPath, symlinkPath);

      // Resolve the symlink
      const resolvedPath = await service.fullyResolvePath(symlinkPath);

      // Should resolve to the target path
      expect(resolvedPath).toBe(path.normalize(targetPath));
    });

    it("should reject symlinks pointing outside allowed directories", async () => {
      // Create target file in outside (non-allowed) directory
      const targetPath = path.join(OUTSIDE_DIR, "target.txt");
      await fs.writeFile(targetPath, TEST_CONTENT, "utf8");

      // Create symlink in test (allowed) directory pointing to outside
      const symlinkPath = path.join(TEST_DIR, "bad-symlink.txt");

      // Setup service with only TEST_DIR allowed (not OUTSIDE_DIR)
      const restrictedService = new FileSecurityService([TEST_DIR]);

      await fs.symlink(targetPath, symlinkPath);

      // Try to resolve the symlink
      await expect(
        restrictedService.fullyResolvePath(symlinkPath)
      ).rejects.toThrow(ValidationError);
      await expect(
        restrictedService.fullyResolvePath(symlinkPath)
      ).rejects.toThrow(/Security error/);
      await expect(
        restrictedService.fullyResolvePath(symlinkPath)
      ).rejects.toThrow(/outside allowed directories/);
    });

    it("should detect and validate symlinked parent directories", async () => {
      // Create target directory in allowed location
      const targetDir = path.join(TEST_DIR, "target-dir");
      await fs.mkdir(targetDir, { recursive: true });

      // Create symlink to directory
      const symlinkDir = path.join(TEST_DIR, "symlink-dir");
      await fs.symlink(targetDir, symlinkDir);

      // Create a file path inside the symlinked directory
      const filePath = path.join(symlinkDir, "test-file.txt");

      // Resolve the path
      const resolvedPath = await service.fullyResolvePath(filePath);

      // Should resolve to actual path in target directory
      const expectedPath = path.join(targetDir, "test-file.txt");
      expect(resolvedPath).toBe(path.normalize(expectedPath));
    });

    it("should reject symlinked parent directories pointing outside allowed directories", async () => {
      // Create target directory in outside (not allowed) directory
      const targetDir = path.join(OUTSIDE_DIR, "target-dir");
      await fs.mkdir(targetDir, { recursive: true });

      // Create symlink in test directory pointing to outside directory
      const symlinkDir = path.join(TEST_DIR, "bad-symlink-dir");
      await fs.symlink(targetDir, symlinkDir);

      // Create a file path inside the symlinked directory
      const filePath = path.join(symlinkDir, "test-file.txt");

      // Setup service with only TEST_DIR allowed
      const restrictedService = new FileSecurityService([TEST_DIR]);

      // Try to resolve the path
      await expect(
        restrictedService.fullyResolvePath(filePath)
      ).rejects.toThrow(ValidationError);
      await expect(
        restrictedService.fullyResolvePath(filePath)
      ).rejects.toThrow(/Security error/);
    });
  });

  describe("secureWriteFile", () => {
    let service: FileSecurityService;

    beforeEach(() => {
      service = new FileSecurityService([TEST_DIR]);
    });

    it("should write file to an allowed directory", async () => {
      const filePath = path.join(TEST_DIR, "test-file.txt");

      await service.secureWriteFile(filePath, TEST_CONTENT);

      // Verify file was written
      const content = await fs.readFile(filePath, "utf8");
      expect(content).toBe(TEST_CONTENT);
    });

    it("should create directories if they don't exist", async () => {
      const nestedFilePath = path.join(
        TEST_DIR,
        "nested",
        "deep",
        "test-file.txt"
      );

      await service.secureWriteFile(nestedFilePath, TEST_CONTENT);

      // Verify directories were created and file exists
      const content = await fs.readFile(nestedFilePath, "utf8");
      expect(content).toBe(TEST_CONTENT);
    });

    it("should reject writing outside allowed directories", async () => {
      const outsidePath = path.join(OUTSIDE_DIR, "test-file.txt");

      await expect(
        service.secureWriteFile(outsidePath, TEST_CONTENT)
      ).rejects.toThrow(ValidationError);
      await expect(
        service.secureWriteFile(outsidePath, TEST_CONTENT)
      ).rejects.toThrow(/Access denied/);

      // Verify file was not created
      await expect(fs.access(outsidePath)).rejects.toThrow();
    });

    it("should reject overwriting existing files by default", async () => {
      const filePath = path.join(TEST_DIR, "existing-file.txt");

      // Create the file first
      await fs.writeFile(filePath, "Original content", "utf8");

      // Try to overwrite without setting overwrite flag
      await expect(
        service.secureWriteFile(filePath, TEST_CONTENT)
      ).rejects.toThrow(ValidationError);
      await expect(
        service.secureWriteFile(filePath, TEST_CONTENT)
      ).rejects.toThrow(/File already exists/);

      // Verify file wasn't changed
      const content = await fs.readFile(filePath, "utf8");
      expect(content).toBe("Original content");
    });

    it("should allow overwriting existing files with overwrite flag", async () => {
      const filePath = path.join(TEST_DIR, "existing-file.txt");

      // Create the file first
      await fs.writeFile(filePath, "Original content", "utf8");

      // Overwrite with overwrite flag
      await service.secureWriteFile(filePath, TEST_CONTENT, {
        overwrite: true,
      });

      // Verify file was overwritten
      const content = await fs.readFile(filePath, "utf8");
      expect(content).toBe(TEST_CONTENT);
    });

    it("should support custom allowed directories", async () => {
      // Path is outside the service's configured directories
      const customAllowedPath = path.join(OUTSIDE_DIR, "custom-allowed.txt");

      // Use explicit allowedDirs
      await service.secureWriteFile(customAllowedPath, TEST_CONTENT, {
        allowedDirs: [OUTSIDE_DIR],
      });

      // Verify file was written
      const content = await fs.readFile(customAllowedPath, "utf8");
      expect(content).toBe(TEST_CONTENT);
    });
  });
});

import { describe, it, beforeEach, afterEach, expect, vi } from "vitest";
import * as path from "node:path";
import * as fs from "node:fs/promises";

// Import the code to test
import { FileSecurityService } from "../../../src/utils/FileSecurityService.js";
import { logger } from "../../../src/utils/logger.js";

describe("FileSecurityService Basic Operations", () => {
  // Define test constants for all tests
  const TEST_CONTENT = "Test file content";

  // Test directories for our tests
  const testDir = path.resolve("./test-temp-dir");
  const subDir = path.join(testDir, "sub-dir");
  const outsideDir = path.resolve("./outside-dir");
  const ALLOWED_DIR = path.join(testDir, "allowed");

  // Setup and teardown for tests
  beforeEach(async () => {
    // Setup test directories
    await fs.mkdir(testDir, { recursive: true });
    await fs.mkdir(ALLOWED_DIR, { recursive: true });
    await fs.mkdir(outsideDir, { recursive: true });

    // Mock logger to prevent console spam
    vi.spyOn(logger, "info").mockImplementation(vi.fn());
    vi.spyOn(logger, "error").mockImplementation(vi.fn());
    vi.spyOn(logger, "warn").mockImplementation(vi.fn());
  });

  afterEach(async () => {
    // Clean up test directories
    await fs.rm(testDir, { recursive: true, force: true });
    await fs.rm(outsideDir, { recursive: true, force: true });

    // Restore mocks
    vi.restoreAllMocks();
  });

  describe("Basic File Security Operations", () => {
    it("should write to a file directly within allowed absolute directory", async () => {
      // Arrange
      const filePath = path.join(ALLOWED_DIR, "file.txt");
      const allowedPaths = [ALLOWED_DIR];
      const fileSecurityService = new FileSecurityService(allowedPaths);

      // Act
      await fileSecurityService.secureWriteFile(filePath, TEST_CONTENT);

      // Assert
      const fileContent = await fs.readFile(filePath, "utf8");
      expect(fileContent).toBe(TEST_CONTENT);
    });

    it("should write to a file in a nested subdirectory of allowed directory", async () => {
      // Arrange
      const nestedDir = path.join(ALLOWED_DIR, "subdir");
      const filePath = path.join(nestedDir, "file.txt");
      const allowedPaths = [ALLOWED_DIR];
      const fileSecurityService = new FileSecurityService(allowedPaths);

      // Act
      await fileSecurityService.secureWriteFile(filePath, TEST_CONTENT);

      // Assert
      const fileContent = await fs.readFile(filePath, "utf8");
      expect(fileContent).toBe(TEST_CONTENT);
    });

    it("should allow writing when filePath is an exact match to allowed absolute file path", async () => {
      // Arrange
      const exactFilePath = path.join(ALLOWED_DIR, "exact-file.txt");
      const allowedPaths = [exactFilePath]; // Allowing the exact file path
      const fileSecurityService = new FileSecurityService(allowedPaths);

      // Act
      await fileSecurityService.secureWriteFile(exactFilePath, TEST_CONTENT);

      // Assert
      const fileContent = await fs.readFile(exactFilePath, "utf8");
      expect(fileContent).toBe(TEST_CONTENT);
    });

    it("should throw error when filePath resolves outside allowed paths", async () => {
      // Arrange
      const unsafePath = path.join(outsideDir, "unsafe-file.txt");
      const allowedPaths = [ALLOWED_DIR];
      const fileSecurityService = new FileSecurityService(allowedPaths);

      // Act & Assert
      await expect(
        fileSecurityService.secureWriteFile(unsafePath, TEST_CONTENT)
      ).rejects.toThrow(
        /Access denied: The file path must be within the allowed directories/
      );

      // Additional check that logger.warn was called (FileSecurityService uses warn, not error)
      expect(logger.warn).toHaveBeenCalled();

      // Verify file was not written
      await expect(fs.access(unsafePath)).rejects.toThrow();
    });

    it("should throw error when filePath uses directory traversal to escape allowed path", async () => {
      // Arrange
      const traversalPath = path.join(
        ALLOWED_DIR,
        "subdir",
        "..",
        "..",
        "outside",
        "file.txt"
      );
      const allowedPaths = [ALLOWED_DIR];
      const fileSecurityService = new FileSecurityService(allowedPaths);

      // Act & Assert
      await expect(
        fileSecurityService.secureWriteFile(traversalPath, TEST_CONTENT)
      ).rejects.toThrow(
        /Access denied: The file path must be within the allowed directories/
      );
    });

    it("should use default path when no allowed paths are provided", async () => {
      // Arrange
      const filePath = path.join(process.cwd(), "test-file.txt");
      const fileSecurityService = new FileSecurityService(); // No paths provided uses CWD as default

      try {
        // Act
        await fileSecurityService.secureWriteFile(filePath, TEST_CONTENT);

        // Assert
        const fileContent = await fs.readFile(filePath, "utf8");
        expect(fileContent).toBe(TEST_CONTENT);
      } finally {
        // Cleanup the file created in CWD
        try {
          await fs.unlink(filePath);
        } catch (err) {
          // Ignore error if file doesn't exist
        }
      }
    });

    it("should correctly handle path normalization and resolution", async () => {
      // Arrange
      const complexPath = path.join(
        ALLOWED_DIR,
        ".",
        "subdir",
        "..",
        "normalized-file.txt"
      );
      const allowedPaths = [ALLOWED_DIR];
      const fileSecurityService = new FileSecurityService(allowedPaths);

      // Act
      await fileSecurityService.secureWriteFile(complexPath, TEST_CONTENT);

      // Assert - check the file exists at the normalized location
      const expectedPath = path.join(ALLOWED_DIR, "normalized-file.txt");
      const fileContent = await fs.readFile(expectedPath, "utf8");
      expect(fileContent).toBe(TEST_CONTENT);
    });

    it("should handle multiple allowed paths", async () => {
      // Arrange
      const filePath = path.join(outsideDir, "allowed-outside-file.txt");
      const content = "multi-allowed content";
      const fileSecurityService = new FileSecurityService([
        ALLOWED_DIR,
        outsideDir,
      ]);

      // Act
      await fileSecurityService.secureWriteFile(filePath, content);

      // Assert
      const fileContent = await fs.readFile(filePath, "utf8");
      expect(fileContent).toBe(content);
    });
  });
});

import { describe, it, beforeEach, afterEach, expect, vi } from "vitest";
import * as path from "path";
import * as fs from "fs/promises";
import * as fsSync from "fs";

// Import the code to test
import { FileSecurityService } from "../../../src/utils/FileSecurityService.js";
import { ValidationError } from "../../../src/utils/errors.js";
import { logger } from "../../../src/utils/logger.js";

describe("FileSecurityService", () => {
  // Mock logger
  const loggerMock = {
    info: vi.fn(),
    warn: vi.fn(),
    error: vi.fn(),
    debug: vi.fn(),
  };

  // Define test constants for all tests
  const TEST_CONTENT = "Test file content";
  const TEST_DIR = path.resolve("./test-security-dir");
  const OUTSIDE_DIR = path.resolve("./outside-security-dir");

  // Setup before each test
  beforeEach(() => {
    // Reset mocks and create test directories
    vi.clearAllMocks();

    // Replace logger with mock
    vi.spyOn(logger, "info").mockImplementation(loggerMock.info);
    vi.spyOn(logger, "warn").mockImplementation(loggerMock.warn);
    vi.spyOn(logger, "error").mockImplementation(loggerMock.error);
    vi.spyOn(logger, "debug").mockImplementation(loggerMock.debug);

    // Create test directories
    fsSync.mkdirSync(TEST_DIR, { recursive: true });
    fsSync.mkdirSync(OUTSIDE_DIR, { recursive: true });
  });

  // Cleanup after each test
  afterEach(() => {
    // Restore original logger
    vi.restoreAllMocks();

    // Clean up test directories
    try {
      fsSync.rmSync(TEST_DIR, { recursive: true, force: true });
      fsSync.rmSync(OUTSIDE_DIR, { recursive: true, force: true });
    } catch (err) {
      // Ignore cleanup errors
    }
  });

  describe("Constructor and Configuration", () => {
    it("should initialize with default allowed directories", () => {
      const service = new FileSecurityService();
      const allowedDirs = service.getAllowedDirectories();

      expect(allowedDirs.length).toBeGreaterThan(0);
      expect(allowedDirs).toContain(path.resolve(process.cwd()));
    });

    it("should initialize with custom allowed directories", () => {
      const customDirs = [TEST_DIR, OUTSIDE_DIR];
      const service = new FileSecurityService(customDirs);
      const allowedDirs = service.getAllowedDirectories();

      expect(allowedDirs.length).toBe(2);
      expect(allowedDirs).toContain(path.resolve(TEST_DIR));
      expect(allowedDirs).toContain(path.resolve(OUTSIDE_DIR));
    });

    it("should initialize with a secure base path", () => {
      const service = new FileSecurityService([], TEST_DIR);
      const basePath = service.getSecureBasePath();

      expect(basePath).toBe(path.normalize(TEST_DIR));

      // Verify allowed directories includes the base path
      const allowedDirs = service.getAllowedDirectories();
      expect(allowedDirs).toContain(path.normalize(TEST_DIR));
    });

    it("should set allowed directories", () => {
      const service = new FileSecurityService();
      const newDirs = [TEST_DIR, OUTSIDE_DIR];

      service.setAllowedDirectories(newDirs);
      const allowedDirs = service.getAllowedDirectories();

      expect(allowedDirs.length).toBe(2);
      expect(allowedDirs).toContain(path.normalize(TEST_DIR));
      expect(allowedDirs).toContain(path.normalize(OUTSIDE_DIR));
    });

    it("should throw error when setting empty allowed directories", () => {
      const service = new FileSecurityService();

      expect(() => service.setAllowedDirectories([])).toThrow(ValidationError);
      expect(() => service.setAllowedDirectories([])).toThrow(
        /At least one allowed directory/
      );
    });

    it("should throw error when setting non-absolute allowed directories", () => {
      const service = new FileSecurityService();

      expect(() => service.setAllowedDirectories(["./relative/path"])).toThrow(
        ValidationError
      );
      expect(() => service.setAllowedDirectories(["./relative/path"])).toThrow(
        /Directory path must be absolute/
      );
    });

    it("should set and get secure base path", () => {
      const service = new FileSecurityService();
      service.setSecureBasePath(TEST_DIR);

      const basePath = service.getSecureBasePath();
      expect(basePath).toBe(path.normalize(TEST_DIR));
    });

    it("should throw error when setting non-absolute secure base path", () => {
      const service = new FileSecurityService();

      expect(() => service.setSecureBasePath("./relative/path")).toThrow(
        ValidationError
      );
      expect(() => service.setSecureBasePath("./relative/path")).toThrow(
        /Base path must be absolute/
      );
    });

    it("should configure from environment", () => {
      // Save original env var
      const originalEnvVar = process.env.GEMINI_SAFE_FILE_BASE_DIR;

      // Set env var for test
      process.env.GEMINI_SAFE_FILE_BASE_DIR = TEST_DIR;

      const service = FileSecurityService.configureFromEnvironment();
      const allowedDirs = service.getAllowedDirectories();

      expect(allowedDirs).toContain(path.normalize(TEST_DIR));

      // Restore original env var
      if (originalEnvVar) {
        process.env.GEMINI_SAFE_FILE_BASE_DIR = originalEnvVar;
      } else {
        delete process.env.GEMINI_SAFE_FILE_BASE_DIR;
      }
    });
  });

  describe("Path Validation", () => {
    let service: FileSecurityService;

    beforeEach(() => {
      service = new FileSecurityService([TEST_DIR]);
    });

    it("should validate path within allowed directory", () => {
      const testFilePath = path.join(TEST_DIR, "test-file.txt");
      const validatedPath = service.validateAndResolvePath(testFilePath);

      expect(validatedPath).toBe(path.normalize(testFilePath));
    });

    it("should validate paths with relative components", () => {
      const complexPath = path.join(
        TEST_DIR,
        ".",
        "subdir",
        "..",
        "test-file.txt"
      );
      const validatedPath = service.validateAndResolvePath(complexPath);

      // Should normalize to TEST_DIR/test-file.txt
      const expectedPath = path.normalize(path.join(TEST_DIR, "test-file.txt"));
      expect(validatedPath).toBe(expectedPath);
    });

    it("should reject paths outside allowed directories", () => {
      const outsidePath = path.join(OUTSIDE_DIR, "test-file.txt");

      expect(() => service.validateAndResolvePath(outsidePath)).toThrow(
        ValidationError
      );
      expect(() => service.validateAndResolvePath(outsidePath)).toThrow(
        /Access denied/
      );
    });

    it("should reject paths with directory traversal", () => {
      const traversalPath = path.join(
        TEST_DIR,
        "..",
        "outside",
        "test-file.txt"
      );

      expect(() => service.validateAndResolvePath(traversalPath)).toThrow(
        ValidationError
      );
      expect(() => service.validateAndResolvePath(traversalPath)).toThrow(
        /Access denied/
      );
    });

    it("should check file existence with mustExist option", () => {
      const nonExistentPath = path.join(TEST_DIR, "non-existent.txt");

      expect(() =>
        service.validateAndResolvePath(nonExistentPath, { mustExist: true })
      ).toThrow(ValidationError);
      expect(() =>
        service.validateAndResolvePath(nonExistentPath, { mustExist: true })
      ).toThrow(/File not found/);
    });

    it("should use custom allowed directories when provided", () => {
      // Path is outside the service's configured directory but inside custom allowed dir
      const customAllowedPath = path.join(OUTSIDE_DIR, "custom-allowed.txt");

      const validatedPath = service.validateAndResolvePath(customAllowedPath, {
        allowedDirs: [OUTSIDE_DIR],
      });

      expect(validatedPath).toBe(path.normalize(customAllowedPath));
    });
  });

  describe("isPathWithinAllowedDirs", () => {
    let service: FileSecurityService;

    beforeEach(() => {
      service = new FileSecurityService([TEST_DIR]);
    });

    it("should return true for paths within allowed directories", () => {
      const insidePath = path.join(TEST_DIR, "test-file.txt");
      const result = service.isPathWithinAllowedDirs(insidePath);

      expect(result).toBe(true);
    });

    it("should return true for exact match with allowed directory", () => {
      const result = service.isPathWithinAllowedDirs(TEST_DIR);

      expect(result).toBe(true);
    });

    it("should return false for paths outside allowed directories", () => {
      const outsidePath = path.join(OUTSIDE_DIR, "test-file.txt");
      const result = service.isPathWithinAllowedDirs(outsidePath);

      expect(result).toBe(false);
    });

    it("should return false for paths with directory traversal", () => {
      const traversalPath = path.join(
        TEST_DIR,
        "..",
        "outside",
        "test-file.txt"
      );
      const result = service.isPathWithinAllowedDirs(traversalPath);

      expect(result).toBe(false);
    });

    it("should use custom allowed directories when provided", () => {
      const outsidePath = path.join(OUTSIDE_DIR, "test-file.txt");

      // Should be false with default allowed dirs
      expect(service.isPathWithinAllowedDirs(outsidePath)).toBe(false);

      // Should be true with custom allowed dirs
      expect(service.isPathWithinAllowedDirs(outsidePath, [OUTSIDE_DIR])).toBe(
        true
      );
    });

    it("should return false when no allowed directories exist", () => {
      const result = service.isPathWithinAllowedDirs(TEST_DIR, []);

      expect(result).toBe(false);
    });
  });

  describe("fullyResolvePath", () => {
    let service: FileSecurityService;

    beforeEach(() => {
      service = new FileSecurityService([TEST_DIR, OUTSIDE_DIR]);
    });

    it("should resolve a normal file path", async () => {
      const testPath = path.join(TEST_DIR, "test-file.txt");
      const resolvedPath = await service.fullyResolvePath(testPath);

      expect(resolvedPath).toBe(path.normalize(testPath));
    });

    it("should handle non-existent paths", async () => {
      const nonExistentPath = path.join(
        TEST_DIR,
        "non-existent",
        "test-file.txt"
      );
      const resolvedPath = await service.fullyResolvePath(nonExistentPath);

      expect(resolvedPath).toBe(path.normalize(nonExistentPath));
    });

    it("should resolve and validate a symlink to a file", async () => {
      // Create target file
      const targetPath = path.join(TEST_DIR, "target.txt");
      await fs.writeFile(targetPath, TEST_CONTENT, "utf8");

      // Create symlink
      const symlinkPath = path.join(TEST_DIR, "symlink.txt");
      await fs.symlink(targetPath, symlinkPath);

      // Resolve the symlink
      const resolvedPath = await service.fullyResolvePath(symlinkPath);

      // Should resolve to the target path
      expect(resolvedPath).toBe(path.normalize(targetPath));
    });

    it("should reject symlinks pointing outside allowed directories", async () => {
      // Create target file in outside (non-allowed) directory
      const targetPath = path.join(OUTSIDE_DIR, "target.txt");
      await fs.writeFile(targetPath, TEST_CONTENT, "utf8");

      // Create symlink in test (allowed) directory pointing to outside
      const symlinkPath = path.join(TEST_DIR, "bad-symlink.txt");

      // Setup service with only TEST_DIR allowed (not OUTSIDE_DIR)
      const restrictedService = new FileSecurityService([TEST_DIR]);

      await fs.symlink(targetPath, symlinkPath);

      // Try to resolve the symlink
      await expect(
        restrictedService.fullyResolvePath(symlinkPath)
      ).rejects.toThrow(ValidationError);
      await expect(
        restrictedService.fullyResolvePath(symlinkPath)
      ).rejects.toThrow(/Security error/);
      await expect(
        restrictedService.fullyResolvePath(symlinkPath)
      ).rejects.toThrow(/outside allowed directories/);
    });

    it("should detect and validate symlinked parent directories", async () => {
      // Create target directory in allowed location
      const targetDir = path.join(TEST_DIR, "target-dir");
      await fs.mkdir(targetDir, { recursive: true });

      // Create symlink to directory
      const symlinkDir = path.join(TEST_DIR, "symlink-dir");
      await fs.symlink(targetDir, symlinkDir);

      // Create a file path inside the symlinked directory
      const filePath = path.join(symlinkDir, "test-file.txt");

      // Resolve the path
      const resolvedPath = await service.fullyResolvePath(filePath);

      // Should resolve to actual path in target directory
      const expectedPath = path.join(targetDir, "test-file.txt");
      expect(resolvedPath).toBe(path.normalize(expectedPath));
    });

    it("should reject symlinked parent directories pointing outside allowed directories", async () => {
      // Create target directory in outside (not allowed) directory
      const targetDir = path.join(OUTSIDE_DIR, "target-dir");
      await fs.mkdir(targetDir, { recursive: true });

      // Create symlink in test directory pointing to outside directory
      const symlinkDir = path.join(TEST_DIR, "bad-symlink-dir");
      await fs.symlink(targetDir, symlinkDir);

      // Create a file path inside the symlinked directory
      const filePath = path.join(symlinkDir, "test-file.txt");

      // Setup service with only TEST_DIR allowed
      const restrictedService = new FileSecurityService([TEST_DIR]);

      // Try to resolve the path
      await expect(
        restrictedService.fullyResolvePath(filePath)
      ).rejects.toThrow(ValidationError);
      await expect(
        restrictedService.fullyResolvePath(filePath)
      ).rejects.toThrow(/Security error/);
    });
  });

  describe("secureWriteFile", () => {
    let service: FileSecurityService;

    beforeEach(() => {
      service = new FileSecurityService([TEST_DIR]);
    });

    it("should write file to an allowed directory", async () => {
      const filePath = path.join(TEST_DIR, "test-file.txt");

      await service.secureWriteFile(filePath, TEST_CONTENT);

      // Verify file was written
      const content = await fs.readFile(filePath, "utf8");
      expect(content).toBe(TEST_CONTENT);
    });

    it("should create directories if they don't exist", async () => {
      const nestedFilePath = path.join(
        TEST_DIR,
        "nested",
        "deep",
        "test-file.txt"
      );

      await service.secureWriteFile(nestedFilePath, TEST_CONTENT);

      // Verify directories were created and file exists
      const content = await fs.readFile(nestedFilePath, "utf8");
      expect(content).toBe(TEST_CONTENT);
    });

    it("should reject writing outside allowed directories", async () => {
      const outsidePath = path.join(OUTSIDE_DIR, "test-file.txt");

      await expect(
        service.secureWriteFile(outsidePath, TEST_CONTENT)
      ).rejects.toThrow(ValidationError);
      await expect(
        service.secureWriteFile(outsidePath, TEST_CONTENT)
      ).rejects.toThrow(/Access denied/);

      // Verify file was not created
      await expect(fs.access(outsidePath)).rejects.toThrow();
    });

    it("should reject overwriting existing files by default", async () => {
      const filePath = path.join(TEST_DIR, "existing-file.txt");

      // Create the file first
      await fs.writeFile(filePath, "Original content", "utf8");

      // Try to overwrite without setting overwrite flag
      await expect(
        service.secureWriteFile(filePath, TEST_CONTENT)
      ).rejects.toThrow(ValidationError);
      await expect(
        service.secureWriteFile(filePath, TEST_CONTENT)
      ).rejects.toThrow(/File already exists/);

      // Verify file wasn't changed
      const content = await fs.readFile(filePath, "utf8");
      expect(content).toBe("Original content");
    });

    it("should allow overwriting existing files with overwrite flag", async () => {
      const filePath = path.join(TEST_DIR, "existing-file.txt");

      // Create the file first
      await fs.writeFile(filePath, "Original content", "utf8");

      // Overwrite with overwrite flag
      await service.secureWriteFile(filePath, TEST_CONTENT, {
        overwrite: true,
      });

      // Verify file was overwritten
      const content = await fs.readFile(filePath, "utf8");
      expect(content).toBe(TEST_CONTENT);
    });

    it("should support custom allowed directories", async () => {
      // Path is outside the service's configured directories
      const customAllowedPath = path.join(OUTSIDE_DIR, "custom-allowed.txt");

      // Use explicit allowedDirs
      await service.secureWriteFile(customAllowedPath, TEST_CONTENT, {
        allowedDirs: [OUTSIDE_DIR],
      });

      // Verify file was written
      const content = await fs.readFile(customAllowedPath, "utf8");
      expect(content).toBe(TEST_CONTENT);
    });
  });
});

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { UrlSecurityService } from '../../../src/utils/UrlSecurityService.js';
import { ConfigurationManager } from '../../../src/config/ConfigurationManager.js';
import { GeminiUrlValidationError } from '../../../src/utils/geminiErrors.js';

// Mock dependencies
vi.mock('../../../src/config/ConfigurationManager.js');
vi.mock('../../../src/utils/logger.js');

describe('UrlSecurityService', () => {
  let service: UrlSecurityService;
  let mockConfig: any;

  beforeEach(() => {
    vi.clearAllMocks();

    mockConfig = {
      getUrlContextConfig: vi.fn().mockReturnValue({
        allowedDomains: ['*'],
        blocklistedDomains: []
      })
    };

    service = new UrlSecurityService(mockConfig as ConfigurationManager);
  });

  describe('URL format validation', () => {
    it('should accept valid HTTP URLs', async () => {
      await expect(service.validateUrl('http://example.com')).resolves.not.toThrow();
    });

    it('should accept valid HTTPS URLs', async () => {
      await expect(service.validateUrl('https://example.com')).resolves.not.toThrow();
    });

    it('should reject invalid URL formats', async () => {
      await expect(service.validateUrl('not-a-url')).rejects.toThrow(GeminiUrlValidationError);
      await expect(service.validateUrl('')).rejects.toThrow(GeminiUrlValidationError);
      await expect(service.validateUrl('   ')).rejects.toThrow(GeminiUrlValidationError);
    });

    it('should reject non-HTTP protocols', async () => {
      await expect(service.validateUrl('ftp://example.com')).rejects.toThrow(GeminiUrlValidationError);
      await expect(service.validateUrl('file:///etc/passwd')).rejects.toThrow(GeminiUrlValidationError);
      await expect(service.validateUrl('javascript:alert(1)')).rejects.toThrow(GeminiUrlValidationError);
      await expect(service.validateUrl('data:text/plain;base64,SGVsbG8=')).rejects.toThrow(GeminiUrlValidationError);
    });
  });

  describe('Domain validation', () => {
    it('should allow domains in allowlist', async () => {
      mockConfig.getUrlContextConfig.mockReturnValue({
        allowedDomains: ['example.com', 'test.org'],
        blocklistedDomains: []
      });

      await expect(service.validateUrl('https://example.com')).resolves.not.toThrow();
      await expect(service.validateUrl('https://test.org')).resolves.not.toThrow();
    });

    it('should reject domains not in allowlist', async () => {
      mockConfig.getUrlContextConfig.mockReturnValue({
        allowedDomains: ['example.com'],
        blocklistedDomains: []
      });

      await expect(service.validateUrl('https://malicious.com')).rejects.toThrow(GeminiUrlValidationError);
    });

    it('should handle wildcard allowlist', async () => {
      mockConfig.getUrlContextConfig.mockReturnValue({
        allowedDomains: ['*'],
        blocklistedDomains: []
      });

      await expect(service.validateUrl('https://any-domain.com')).resolves.not.toThrow();
    });

    it('should handle subdomain patterns', async () => {
      mockConfig.getUrlContextConfig.mockReturnValue({
        allowedDomains: ['*.example.com'],
        blocklistedDomains: []
      });

      await expect(service.validateUrl('https://sub.example.com')).resolves.not.toThrow();
      await expect(service.validateUrl('https://deep.sub.example.com')).resolves.not.toThrow();
      await expect(service.validateUrl('https://example.com')).resolves.not.toThrow();
      await expect(service.validateUrl('https://other.com')).rejects.toThrow(GeminiUrlValidationError);
    });

    it('should block domains in blocklist', async () => {
      mockConfig.getUrlContextConfig.mockReturnValue({
        allowedDomains: ['*'],
        blocklistedDomains: ['malicious.com', 'spam.net']
      });

      await expect(service.validateUrl('https://malicious.com')).rejects.toThrow(GeminiUrlValidationError);
      await expect(service.validateUrl('https://spam.net')).rejects.toThrow(GeminiUrlValidationError);
      await expect(service.validateUrl('https://safe.com')).resolves.not.toThrow();
    });

    it('should block subdomains of blocklisted domains', async () => {
      mockConfig.getUrlContextConfig.mockReturnValue({
        allowedDomains: ['*'],
        blocklistedDomains: ['malicious.com']
      });

      await expect(service.validateUrl('https://sub.malicious.com')).rejects.toThrow(GeminiUrlValidationError);
    });
  });

  describe('Private network protection', () => {
    it('should block localhost addresses', async () => {
      await expect(service.validateUrl('http://localhost')).rejects.toThrow(GeminiUrlValidationError);
      await expect(service.validateUrl('http://127.0.0.1')).rejects.toThrow(GeminiUrlValidationError);
      await expect(service.validateUrl('http://0.0.0.0')).rejects.toThrow(GeminiUrlValidationError);
    });

    it('should block private IP ranges', async () => {
      await expect(service.validateUrl('http://192.168.1.1')).rejects.toThrow(GeminiUrlValidationError);
      await expect(service.validateUrl('http://10.0.0.1')).rejects.toThrow(GeminiUrlValidationError);
      await expect(service.validateUrl('http://172.16.0.1')).rejects.toThrow(GeminiUrlValidationError);
    });

    it('should block internal domain extensions', async () => {
      await expect(service.validateUrl('http://server.local')).rejects.toThrow(GeminiUrlValidationError);
      await expect(service.validateUrl('http://api.internal')).rejects.toThrow(GeminiUrlValidationError);
      await expect(service.validateUrl('http://db.corp')).rejects.toThrow(GeminiUrlValidationError);
    });

    it('should allow public IP addresses', async () => {
      await expect(service.validateUrl('http://8.8.8.8')).resolves.not.toThrow();
      await expect(service.validateUrl('http://1.1.1.1')).resolves.not.toThrow();
    });
  });

  describe('Suspicious pattern detection', () => {
    it('should detect path traversal attempts', async () => {
      await expect(service.validateUrl('http://example.com/../../../etc/passwd')).rejects.toThrow(GeminiUrlValidationError);
      await expect(service.validateUrl('http://example.com/path/with/../dots')).rejects.toThrow(GeminiUrlValidationError);
    });

    it('should detect dangerous characters', async () => {
      await expect(service.validateUrl('http://example.com/path<script>')).rejects.toThrow(GeminiUrlValidationError);
      await expect(service.validateUrl('http://example.com/path{malicious}')).rejects.toThrow(GeminiUrlValidationError);
    });

    it('should detect multiple @ symbols', async () => {
      await expect(service.validateUrl('http://user@pass@example.com')).rejects.toThrow(GeminiUrlValidationError);
    });

    it('should allow normal URLs with safe characters', async () => {
      await expect(service.validateUrl('https://example.com/path/to/resource?param=value&other=123')).resolves.not.toThrow();
      await expect(service.validateUrl('https://api.example.com/v1/users/123')).resolves.not.toThrow();
