  private timeout: number;
  private eventSource?: EventSource;

  constructor(options: MCPTestClientOptions) {
    this.url = options.url;
    this.timeout = options.timeout || 30000;
  }

  async initialize(): Promise<any> {
    const response = await fetch(this.url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json, text/event-stream",
      },
      body: JSON.stringify({
        jsonrpc: "2.0",
        id: 1,
        method: "initialize",
        params: {
          protocolVersion: "2024-11-05",
          capabilities: {
            tools: {},
          },
          clientInfo: {
            name: "mcp-test-client",
            version: "1.0.0",
          },
        },
      }),
    });

    this.sessionId = response.headers.get("Mcp-Session-Id") || undefined;
    const result = await this.parseResponse(response);

    if (result.error) {
      throw new Error(`Initialize failed: ${result.error.message}`);
    }

    return result.result;
  }

  async listTools(): Promise<any[]> {
    if (!this.sessionId) {
      throw new Error("Not initialized - call initialize() first");
    }

    const response = await fetch(this.url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json, text/event-stream",
        "Mcp-Session-Id": this.sessionId,
      },
      body: JSON.stringify({
        jsonrpc: "2.0",
        id: 2,
        method: "tools/list",
        params: {},
      }),
    });

    const result = await this.parseResponse(response);

    if (result.error) {
      throw new Error(`List tools failed: ${result.error.message}`);
    }

    return result.result.tools;
  }

  async callTool(name: string, args: any): Promise<any> {
    if (!this.sessionId) {
      throw new Error("Not initialized - call initialize() first");
    }

    const response = await fetch(this.url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json, text/event-stream",
        "Mcp-Session-Id": this.sessionId,
      },
      body: JSON.stringify({
        jsonrpc: "2.0",
        id: Date.now(),
        method: "tools/call",
        params: {
          name,
          arguments: args,
        },
      }),
    });

    const result = await this.parseResponse(response);

    if (result.error) {
      throw new Error(`Tool call failed: ${result.error.message}`);
    }

    return result.result;
  }

  async streamTool(name: string, args: any): Promise<AsyncIterable<any>> {
    if (!this.sessionId) {
      throw new Error("Not initialized - call initialize() first");
    }

    // For streaming, we need to handle SSE
    const url = `${this.url}?sessionId=${this.sessionId}`;
    this.eventSource = new EventSource(url);

    // Send the request to trigger streaming
    await fetch(this.url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "text/event-stream",
        "Mcp-Session-Id": this.sessionId,
      },
      body: JSON.stringify({
        jsonrpc: "2.0",
        id: Date.now(),
        method: "tools/call",
        params: {
          name,
          arguments: args,
        },
      }),
    });

    // Return async iterable for streaming data
    const eventSource = this.eventSource;
    return {
      async *[Symbol.asyncIterator]() {
        const chunks: any[] = [];
        let done = false;

        eventSource.onmessage = (event) => {
          const data = JSON.parse(event.data);
          chunks.push(data);
        };

        eventSource.onerror = () => {
          done = true;
          eventSource.close();
        };

        while (!done) {
          if (chunks.length > 0) {
            yield chunks.shift();
          } else {
            await new Promise((resolve) => setTimeout(resolve, 10));
          }
        }
      },
    };
  }

  async disconnect(): Promise<void> {
    if (this.eventSource) {
      this.eventSource.close();
    }

    if (this.sessionId) {
      // Send disconnect/cleanup request if needed
      await fetch(this.url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Mcp-Session-Id": this.sessionId,
        },
        body: JSON.stringify({
          jsonrpc: "2.0",
          id: Date.now(),
          method: "disconnect",
          params: {},
        }),
      }).catch(() => {
        // Ignore errors on disconnect
      });
    }

    this.sessionId = undefined;
  }

  private async parseResponse(response: Response): Promise<any> {
    const contentType = response.headers.get("content-type") || "";

    if (contentType.includes("text/event-stream")) {
      // Parse SSE format
      const text = await response.text();
      const lines = text.split("\n");

      for (const line of lines) {
        if (line.startsWith("data: ")) {
          try {
            return JSON.parse(line.substring(6));
          } catch (e) {
            // Continue to next line
          }
        }
      }

      throw new Error("No valid JSON data in SSE response");
    } else {
      // Standard JSON response
      return response.json();
    }
  }
}

