        throw error;
      });

      await expect(retryService.execute(fn)).rejects.toThrow(
        "Non-retryable error"
      );
      expect(fn).toHaveBeenCalledTimes(1); // No retries
      expect(onRetryMock).not.toHaveBeenCalled();
    });

    it("should use custom retryable error check if provided", async () => {
